import{_ as o,l as s,o as e,c as l,v as t,p as n,x as i,d as P,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"BGP 属性与决策","description":"","frontmatter":{"title":"BGP 属性与决策","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bgp-attributes-decision.md","filePath":"cs/bgp-attributes-decision.md","lastUpdated":1789023840000}'),_={name:"cs/bgp-attributes-decision.md"};function c(A,a,E,h,B,u){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="bgp-属性与决策" tabindex="-1">BGP 属性与决策 <a class="header-anchor" href="#bgp-属性与决策" aria-label="Permalink to &quot;BGP 属性与决策&quot;">​</a></h1><div class="epigraph"><p>同一前缀多条路径时，决策过程按 LOCAL_PREF、AS_PATH、ORIGIN、MED、eBGP vs iBGP、IGP 度量、Router ID 逐步打破平局。</p><footer>—— 据 RFC 4271 第 9.1 节决策过程；Kurose and Ross BGP 属性整理</footer></div><p>主干<a href="/cs/bgp-policy">AS 路径与策略</a> 已给进出口直觉。<a href="/cs/rip">上一课</a> 对照了无政策的跳数。<a href="/cs/bgp-intuition">BGP 直觉</a> 不背阶梯。缺口是<strong>属性怎么排序</strong>：谁先谁后、哪些过 iBGP、哪些不。本课不把路由反射器写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IGP 选最小代价。BGP 选「政策最佳」。典型顺序：拒无效 → 最高 LOCAL_PREF → 最短 AS_PATH → 最低 ORIGIN → 最低 MED（同 AS）→ 偏 eBGP → 最近 IGP 下一跳 → 其它平局。LOCAL_PREF 不发给 eBGP 邻居，故是 AS 内部的客户优先旋钮。MED 可对外暗示入口，邻居可无视。</p><p>不要把 AS_PATH 长度当延迟：绕远可以是故意的 LOCAL_PREF。</p><p><span class="marginnote">RFC 4271。厂商在阶梯里插入权重等私有步，课上以标准为主。Communities 是政策标签，本身不是阶梯里的一步，除非你的政策把它映到 LOCAL_PREF。</span></p><h3 id="不是最短跳" tabindex="-1">不是最短跳 <a class="header-anchor" href="#不是最短跳" aria-label="Permalink to &quot;不是最短跳&quot;">​</a></h3><p>LOCAL_PREF 内部优先于 AS_PATH。MED 可被邻居无视。下一跳必须 IGP 可达才有效。Communities 要映到阶梯才起作用。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>走一条例子：客户路由 vs 对等路由，LOCAL_PREF 已决定。再走 MED 选入口。画决策漏斗。对照 RIP：没有这些属性，无法表达合同。</p>',11)),(e(),n(d,null,{default:i(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%80%99%E9%80%89%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20LP%5B%22LOCAL_PREF%22%5D%0A%20%20LP%20--%3E%20ASP%5B%22AS_PATH%20%E9%95%BF%22%5D%0A%20%20ASP%20--%3E%20MED%5B%22MED%22%5D%0A%20%20MED%20--%3E%20NH%5B%22IGP%20%E5%88%B0%E4%B8%8B%E4%B8%80%E8%B7%B3%22%5D%0A%20%20NH%20--%3E%20BEST%5B%22%E5%AE%89%E8%A3%85%20FIB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[P(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选出的下一跳还要 IGP 可达（递归），否则无效——这把域内 SPF 与域间政策接起来。ECMP 在 BGP 里默认常关，多路径要额外开，避免环与不对称。主干 LPM 课：FIB 仍按最长前缀，BGP 只是填充某前缀的下一跳。</p><p>收敛慢：属性抖动会反复决策，后课 dampening。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ADD-PATH 的全部。iBGP 与路由反射器是下一课。后课默认：eBGP 政策阶梯以 RFC 4271 为准；私有步要显式声明。</p><p>不要用 MED 当全球负载均衡：它只在同意比较的 AS 之间有意义。</p><p>上一课留下的缺口在本课收口；「BGP 属性与决策」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ibgp-route-reflector">iBGP 与路由反射器</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策是属性漏斗，不是最短跳。</li><li>LOCAL_PREF 内部，MED 对外可被忽略。</li><li>下一跳必须 IGP 可达。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4271；Kurose and Ross。</li></ul>',10))])}const G=o(_,[["render",c]]);export{b as __pageData,G as default};
